import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"Project Status","description":"The current version of Hearth, what has been completed, what has not yet started, and the next-phase plan.","frontmatter":{"title":"Project Status","description":"The current version of Hearth, what has been completed, what has not yet started, and the next-phase plan.","outline":[2,3]},"headers":[],"relativePath":"en/guide/project-status.md","filePath":"en/guide/project-status.md","lastUpdated":1793752688000}'),r={name:"en/guide/project-status.md"};function i(l,e,d,s,c,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<p class="eyebrow">PROJECT STATUS</p><h1 id="project-status" tabindex="-1">Project Status <a class="header-anchor" href="#project-status" aria-label="Permalink to &quot;Project Status&quot;">​</a></h1><p class="lead">Hearth is currently in the specification and roadmap stage. The repository already contains a complete product, architecture, security, evaluation, and delivery plan, but implementation has not yet begun.</p><h2 id="documentation-and-project-status" tabindex="-1">Documentation and Project Status <a class="header-anchor" href="#documentation-and-project-status" aria-label="Permalink to &quot;Documentation and Project Status&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Status</th></tr></thead><tbody><tr><td>Documentation source</td><td>Curated product, architecture, security, and delivery roadmap</td></tr><tr><td>Repository</td><td><code>hearthproject/hearth-os</code></td></tr><tr><td>Phase</td><td>Specification &amp; planning</td></tr><tr><td>Implementation</td><td>Not yet started</td></tr><tr><td>Next milestone</td><td>Stage 0: Product truth, prototype, protocols, and evaluation baseline</td></tr><tr><td>License</td><td>Apache-2.0</td></tr></tbody></table><h2 id="completed" tabindex="-1">Completed <a class="header-anchor" href="#completed" aria-label="Permalink to &quot;Completed&quot;">​</a></h2><ul><li>Product definition, non-goals, and primary users;</li><li>Coverage of eight Task categories, autonomy levels, and the definition of “done”;</li><li>Seven planes, domain entities, Event, Executor, and Receipt protocols;</li><li>Entry point, Control Plane, Durable Harness, Executor, and human takeover design;</li><li>Execution security, memory, evolution, Token economics, frontend, and mobile experience;</li><li>Security, privacy, threat model, and evaluation framework;</li><li>Stage 0–6 product roadmap and a progressive development plan from 0 to 100;</li><li>Engineering structure, risks, Kill Criteria, ADR index, and appendices;</li><li>A deployable bilingual Chinese/English documentation site.</li></ul><h2 id="not-started" tabindex="-1">Not Started <a class="header-anchor" href="#not-started" aria-label="Permalink to &quot;Not Started&quot;">​</a></h2><ul><li>A runnable <code>hearthd</code>, <code>hearth</code> CLI, and Web interface;</li><li>Stage 0 clickable prototype and real data contracts;</li><li>The first real slice of Codex Executor;</li><li>Connector, Browser, GUI, and Document/Data Executors;</li><li>Memory OS, Evolution OS, and multi-device synchronization.</li></ul><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><p>The goal of Stage 0 is not to “write more documentation,” but to pin down the product, interaction, protocols, and acceptance criteria:</p><ol><li>Select the first high-frequency, low-external-risk Task family;</li><li>Produce a clickable end-to-end Web prototype;</li><li>Define projection fields and primary actions for each UI state;</li><li>Freeze schema v0 for Event, Task, Run, Executor, Approval, and Receipt;</li><li>Establish an evaluation Task set, validators, and a threat model baseline.</li></ol><p>See the <a href="/hearth-os/en/delivery/development-plan.html">Development Plan</a> for Stage 0 exit criteria, the increment checklist, and the acceptance template.</p><h2 id="how-to-follow-along" tabindex="-1">How to Follow Along <a class="header-anchor" href="#how-to-follow-along" aria-label="Permalink to &quot;How to Follow Along&quot;">​</a></h2><ul><li>Read the <a href="/hearth-os/en/delivery/roadmap.html">phased product roadmap</a> to understand the capability thresholds;</li><li>Read the <a href="/hearth-os/en/delivery/development-plan.html">0 to 100 development plan</a> to understand the first implementation sequence;</li><li>Follow repository commits and Issues;</li><li>If you want to contribute to documentation or implementation, please read <a href="/hearth-os/en/reference/contributing.html">Contributing and Documentation Maintenance</a> first.</li></ul>',15)])])}const m=t(r,[["render",i]]);export{u as __pageData,m as default};
